 rows=[
 ('punkte','Punkte oder Linie?',['l5','l6','l7'],'Begriffe auseinanderhalten.','Für die ausgedachte Firma {firma}: Gib mir nacheinander vier kurze Beispiele für Monitoring, Logging, Tracing und Evaluation, ohne die Lösung vorwegzunehmen. Nach meiner Einordnung erkläre, warum sie passt oder nicht passt.','Monitoring misst Signale, Logs sind Ereignisse, Traces verbinden Schritte, Evaluation prüft Qualität.'),
 ('ursache','Der erste falsche Schritt',['l2','l16'],'Ursache und Folge trennen.','Erfinde einen vierstufigen Ablauf bei {firma}: Suche wählt eine alte Quelle, Modell übernimmt die Zahl, Werkzeug verarbeitet sie korrekt, finale Antwort klingt sicher. Lass mich die erste Abweichung und eine passende Verbesserung begründen.','Zuerst die veraltete Quelle identifizieren und die Auswahl verbessern; nur den letzten Satz umzuschreiben löst die Ursache nicht.'),
 ('kriterien','Gut nach welchem Maßstab?',['l8','l9'],'Prüfkriterien festlegen.','Erstelle zwei kurze, ausdrücklich erfundene KI-Antworten zu {produkt} von {firma}. Eine ist schnell und sachlich falsch, die andere langsamer und belegt. Gib eine feste Referenz mit. Lass mich Quelle, Fakten und Format getrennt bewerten.','Die Bewertung braucht eine Referenz. Schneller heißt nicht besser.'),
 ('zeiten','Warum dauert das so lange?',['l11','l12'],'Zeitpfade verstehen.','Erfinde einen seriellen Verlauf mit vier Zeitangaben und einen Verlauf mit zwei parallelen Werkzeugen. Lass mich Gesamtdauer und längsten Schritt bestimmen. Gib die Lösung erst nach meinem Versuch.','Serielle Dauern addieren; parallele Pfade nach ihrer wirklichen Überlappung beurteilen.'),
 ('blind','Die ehrliche Messlücke',['l10','l13'],'Nicht beobachtet von nicht passiert unterscheiden.','Bei {firma} enthält ein erfundener Trace nur Start und Antwort; Tool-Schritte und Kosten fehlen. Lass mich drei zulässige Aussagen und drei unbelegte Vermutungen trennen.','Fehlende Aufzeichnungen sind kein Beweis, dass keine Werkzeuge liefen; unbekannte Kosten nicht null nennen.'),
 ('probe','Eine Änderung, derselbe Test',['l3','l8'],'Verbesserungen überprüfbar machen.','Für einen allgemeinen Text zu {produkt}: Plane drei erfundene Testfälle mit Referenz, gleichen Qualitätskriterien und wiederholten Läufen vor/nach genau einer Änderung. Keine echten Messwerte behaupten.','Gleiche Fälle und Kriterien ermöglichen einen Vergleich; ein Erfolg ist keine Zuverlässigkeitsgarantie.')]
 short=[M('t14-'+id,14,title,10,learn,goal,'Alle Angaben zu {firma} ({was}) sind ausgedacht.',[('Im normalen Langdock-Chat starten:',prompt),('Ergebnis mit „Einfach erklärt“ vergleichen und einen eigenen Merksatz notieren.',None)],'Keine echten Logs, Kundendaten oder Zugangsschlüssel verwenden. Die KI darf keine echte Messung behaupten.',loesung=solution) for id,title,learn,goal,prompt,solution in rows]
 deep=[DL('dl-observability-cockpit',14,14,'Die Antwort unter der Lupe',[(14,'l2'),(14,'l7'),(14,'l8'),(14,'l9'),(14,'l15')],'Einen erfundenen Lauf erklären und eine Verbesserung kontrolliert prüfen.','ein kommentierter Verlauf, drei Prüfkriterien, ein Vergleich und ein eigener Merksatz.','Die erfundene Firma {firma} nutzt eine KI für einen Text zu {produkt}. Der gesamte Versuch bleibt eine Lernsimulation.',[
 E('Erst beobachten',10,[('Die Spurensuche im Agenten-Cockpit lösen. Bei jedem Schritt Eingabe und Ergebnis lesen.',None)],'Kann man die erste falsche Abzweigung belegen?'),
 E('Den Verlauf selbst erklären',15,[('Im normalen Chat:', 'Erfinde für {firma} einen kurzen Ablauf mit Suche, Auswahl, Werkzeug und Antwort. Eine alte Quelle verursacht einen Folgefehler. Lass mich Ursache und Folge erklären, bevor du auflöst.')],'Wurde ein technischer Erfolg mit inhaltlichem Erfolg verwechselt?'),
 E('Qualität festlegen',10,[('Drei Kriterien mit einer festen erfundenen Referenz formulieren: Quelle, Fakten und Format. Noch keine Variante bewerten.',None)],'Sind die Kriterien vor dem Vergleich festgelegt?'),
 E('Varianten vergleichen',15,[('Das Vergleichslabor im Cockpit öffnen. Qualität, Laufzeit, Tokens und Kosten getrennt notieren. Eine Verbesserung begründen.',None)],'Ist die schnellste Variante auch nach den Kriterien richtig?'),
 E('Transfer festhalten',10,[('Im normalen Chat:', 'Prüfe meinen Merksatz zu Observability kritisch. Stelle eine Rückfrage zu einer Messlücke. Behaupte keine echte Langfuse-Verbindung. Alles bleibt erfunden.')],'Kann man erklären, was ein Trace zeigt und was unbekannt bleibt?')],['Nur erfundene Daten.','Erste Abweichung belegt.','Drei Qualitätskriterien.','Vier Messgrößen verglichen.','Eigener Merksatz und eine offene Frage.'])]
 return short,deep
